'use strict';
(function(){
 const E=window.GhostEngine,D=window.GHOST_DATA,$=id=>document.getElementById(id);let result=[],showAll=false,selected=0,fileSequence=0;
 function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
 function error(text){$('error').textContent=text;$('error').hidden=!text;}
 function read(text,label){try{const next=E.analyze(text,D.model);result=next;showAll=false;selected=-1;$('dataset').textContent=label;error('');render();return true;}catch(e){error(e.message+(result.length?' Previous results remain displayed.':''));return false;}}
 function clear(){fileSequence++;result=[];$('csv').value='';$('file').value='';$('dataset').textContent='No archive open';error('');render();}
 function example(kind){fileSequence++;const text=kind==='quiet'?D.quietCsv:D.hauntedCsv;$('csv').value=text;read(text,'Fictional / '+(kind==='quiet'?'quieter':'haunted'));}
 function state(){return {records:result.length,flagged:result.filter(r=>r.flagged).length,dataset:$('dataset').textContent,selectedRecord:result.length?selected+1:null,visibleRows:$('rows').children.length,error:$('error').hidden?null:$('error').textContent};}
 function detail(item){$('detail').replaceChildren();if(!item)return;const r=item.record;$('detail').append(node('h3','Record '+(item.index+1)+' / a trace, not a conclusion'));const meta=node('p',r.timestamp+' · '+r.source+' · '+r.event,'small');$('detail').append(meta);const ul=node('ul');item.reasons.forEach(x=>ul.append(node('li',x)));$('detail').append(ul,node('p','These notes describe the record. They do not establish why it happened.','small'));}
 function render(){
  const exists=!!result.length;$('empty').hidden=exists;$('results').hidden=!exists;$('download').disabled=!exists;if(!exists){$('timeline').replaceChildren();$('rows').replaceChildren();$('detail').replaceChildren();return;}
  $('count').textContent=result.length.toLocaleString('en-US');$('flags').textContent=result.filter(x=>x.flagged).length.toLocaleString('en-US');
  const max=Math.max(...result.map(z=>z.score)),min=Math.min(...result.map(z=>z.score));$('timeline').replaceChildren();
  for(const item of result){const bar=node('span',undefined,'tracebar'+(item.flagged?' flag':''));bar.style.height=(15+85*(item.score-min)/Math.max(max-min,.001))+'%';bar.title='Record '+(item.index+1)+': '+item.score.toFixed(4);$('timeline').append(bar);}
  const sorted=[...result].sort((a,b)=>b.score-a.score||a.index-b.index);if(!sorted.some(x=>x.index===selected))selected=sorted[0].index;
  $('rows').replaceChildren();for(const item of (showAll?sorted:sorted.slice(0,8))){const r=item.record,tr=node('tr',undefined,item.index===selected?'selected':'');const cell=node('td'),button=node('button',undefined,'rowbutton');button.append(node('b','#'+String(item.index+1).padStart(3,'0')),node('span',new Date(r.timestamp).toISOString().replace('T',' ').slice(0,19)));button.setAttribute('aria-label','Inspect record '+(item.index+1));button.addEventListener('click',()=>{selected=item.index;render();});cell.append(button);const source=node('td');source.append(node('b',r.source),node('span',r.event));const state=node('td');state.append(node('span',item.flagged?'REVIEW':'IN RANGE','state'+(item.flagged?' flag':'')));tr.append(cell,source,node('td',item.score.toFixed(4)),state);$('rows').append(tr);}
  $('all').hidden=result.length<=8;$('all').textContent=showAll?'Show top eight':'Show all '+result.length+' records';
  detail(result.find(z=>z.index===selected));$('announcement').textContent=result.length+' records analyzed; '+result.filter(z=>z.flagged).length+' above the synthetic model threshold.';
 }
 $('haunted').addEventListener('click',()=>example('haunted'));
 $('quiet').addEventListener('click',()=>example('quiet'));
 $('analyze').addEventListener('click',()=>{fileSequence++;read($('csv').value,'Your local CSV');});
 $('all').addEventListener('click',()=>{showAll=!showAll;render();});
 $('clear').addEventListener('click',clear);
 $('file').addEventListener('change',async()=>{const token=++fileSequence;const file=$('file').files[0];if(!file)return;if(file.size>1024*1024){error('CSV is larger than 1 MB.');return;}try{const text=await file.text();if(token!==fileSequence)return;$('csv').value=text;read(text,'Your local CSV');}catch{if(token===fileSequence)error('The local file could not be read.');}});
 function exportReport(){if(!result.length)throw Error('Open an archive before exporting.');const blob=new Blob(['\uFEFF'+E.reportCsv(result)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ghost-logbook-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return {filename:'ghost-logbook-report.csv',records:result.length,bytes:blob.size};}
 $('download').addEventListener('click',exportReport);
 const v=D.model.validation;$('validation').append(node('p','scikit-learn '+D.model.libraryVersion+' · 48 Isolation Forest trees · 2,048 synthetic training rows · seed '+D.model.seed+'.','small'),node('p','A separate 800-row synthetic quiet set produced '+v.syntheticHeldOutFlags+' flags. '+v.craftedOddInTopSix+' of six deliberately altered demonstration rows appeared in the top six scores. These narrowly defined checks are reproducible; they are not real-world accuracy estimates.','small'),node('p','Seven features: log duration, log payload, UTC hour sine/cosine, training-vocabulary rarity of source/event, and error status. Model threshold: '+D.model.flagThreshold.toFixed(6)+'. Unknown source/event names get the documented floor frequency 0.0001.','small'));
 example('haunted');
 // Optional native browser-agent support. The same helpers power UI and tools.
 const registry=document.modelContext;
 if(typeof registry?.registerTool==='function'){
  const lifecycle=new AbortController();
  const objectInput=(input,keys)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!keys.includes(k)))throw Error('Invalid tool input.');return input;};
  const register=tool=>{try{Promise.resolve(registry.registerTool(tool,{signal:lifecycle.signal})).catch(e=>console.warn('Optional archive tool unavailable:',e.message));}catch(e){console.warn('Optional archive tool unavailable:',e.message);}};
  register({name:'load_archive_example',description:'Load one fictional example into this local explorer. Changes the visible archive only; no network requests or real user data.',inputSchema:{type:'object',properties:{kind:{type:'string',enum:['haunted','quiet']}},required:['kind'],additionalProperties:false},execute(input){objectInput(input,['kind']);if(!['haunted','quiet'].includes(input.kind))throw Error('Choose haunted or quiet.');example(input.kind);return state();}});
  register({name:'analyze_archive_csv',description:'Analyze supplied CSV locally and update the visible page. Use only data the user authorized for this tool. Does not transmit the file to a server. Returns counts and validation state, not raw records.',inputSchema:{type:'object',properties:{csv:{type:'string',maxLength:1048576}},required:['csv'],additionalProperties:false},execute(input){objectInput(input,['csv']);if(typeof input.csv!=='string'||input.csv.length>1048576)throw Error('Provide a CSV string up to 1 MB.');fileSequence++;$('csv').value=input.csv;read(input.csv,'Your local CSV');return state();}});
  register({name:'inspect_archive_record',description:'Select a record by one-based file-order number and display its observation notes. Returns only its number and current aggregate state.',inputSchema:{type:'object',properties:{record:{type:'integer',minimum:1,maximum:2000}},required:['record'],additionalProperties:false},execute(input){objectInput(input,['record']);if(!Number.isInteger(input.record)||input.record<1||input.record>result.length)throw Error('Record number is outside this archive.');selected=input.record-1;render();return state();}});
  register({name:'set_archive_rows',description:'Toggle top-eight versus all visible records. No data leaves this page.',inputSchema:{type:'object',properties:{all:{type:'boolean'}},required:['all'],additionalProperties:false},execute(input){objectInput(input,['all']);if(typeof input.all!=='boolean')throw Error('all must be boolean.');showAll=input.all;render();return state();}});
  register({name:'clear_archive',description:'Clear this page\'s working CSV and results. Does not alter any disk file.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute(input){objectInput(input,[]);clear();return state();}});
  register({name:'read_archive_state',description:'Read aggregate archive counts and validation state. Does not return raw CSV or private source/event names.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute(input){objectInput(input,[]);return state();}});
  register({name:'export_archive_report',description:'Download a CSV report for the currently visible archive into the browser download area. No server upload and no disk file is overwritten by this application. Use only when the user wants an export.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute(input){objectInput(input,[]);return exportReport();}});
 }
})();
